#!/usr/bin/env bash
set -Eeuo pipefail
SCRIPT_DIR="$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")" && pwd)"
# shellcheck source=../lib/common.sh
source "$SCRIPT_DIR/../lib/common.sh"
generate() {
  load_node_data; install -d -m 0755 "$WEB_ROOT"
  cat >"$WEB_ROOT/config.yaml" <<EOF
# Generated by Proxy Manager; this file contains no server private key.
mixed-port: 7890
allow-lan: false
mode: rule
log-level: warning
ipv6: false
unified-delay: true
tcp-concurrent: true
packet-encoding: xudp
dns:
  enable: true
  listen: 127.0.0.1:1053
  enhanced-mode: fake-ip
  fake-ip-range: 198.18.0.1/16
  nameserver: [https://1.1.1.1/dns-query, https://dns.google/dns-query]
proxies:
  - name: "$NODE_NAME"
    type: vless
    server: "$SERVER"
    port: $PORT
    uuid: "$UUID"
    encryption: "none"
    network: tcp
    udp: true
    tls: true
    flow: xtls-rprx-vision
    servername: "$SNI"
    client-fingerprint: chrome
    reality-opts:
      public-key: "$PUBLIC_KEY"
      short-id: "$SHORT_ID"
proxy-groups:
  - name: Proxy
    type: select
    proxies:
      - "$NODE_NAME"
      - DIRECT
rules:
  - MATCH,Proxy
EOF
  chmod 0644 "$WEB_ROOT/config.yaml"
  # 自检：历史问题为 nginx 未启动导致订阅空/不可用
  [[ -s "$WEB_ROOT/config.yaml" ]] || die "Clash 配置生成失败（文件为空）。"
  if ! systemctl is-active --quiet nginx 2>/dev/null; then
    say "⚠ 自检: nginx 未运行，订阅 URL 暂时无法访问 —— 请运行主菜单 7 启动 Web 订阅服务。"
  elif command -v curl >/dev/null 2>&1; then
    code=$(curl -o /dev/null -s -w '%{http_code}' "http://127.0.0.1/clash/config.yaml" || true)
    if [[ "$code" == "200" ]]; then say "✓ 自检: 订阅 URL 本地可访问 (HTTP 200)。"; else say "⚠ 自检: 本地请求返回 HTTP ${code:-无响应}（若仅本机测不到公网 IP 属正常，请以浏览器访问为准）。"; fi
  fi
  say "URL: ${SUBSCRIPTION_URL:-http://$SERVER/clash/config.yaml}"
}
case "${1:-}" in generate) require_root; generate; exit;; show) load_node_data; say "$SUBSCRIPTION_URL"; exit;; "") ;; *) die "Usage: subscription.sh [generate|show]";; esac
require_root
while true; do clear; say "===== Clash 订阅 ====="; say "1. 生成配置"; say "2. 显示订阅地址"; say "0. 返回"; read -r -p "请选择: " c; case "$c" in 1) generate; read -r -p "请按回车继续..." _;;2) load_node_data; say "$SUBSCRIPTION_URL"; read -r -p "请按回车继续..." _;;0) exit;;*) say "无效选择。";;esac; done
